package main

import (
	"os"
	"strings"
	"testing"
	"time"
)

func TestProbeExpiryDoc(t *testing.T) {
	// The ttl constant exists and is used.
	if sessionTTL != 30*time.Minute {
		t.Fatalf("sessionTTL = %v, want 30m", sessionTTL)
	}
	src, err := os.ReadFile("main.go")
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(src), "NewStore(30 * time.Minute)") {
		t.Fatal("main still uses the literal; must use sessionTTL")
	}
	readme, err := os.ReadFile("README.md")
	if err != nil {
		t.Fatal(err)
	}
	for _, sentence := range []string{
		"A session expires after 30 minutes of inactivity.",
		"Reading a session refreshes its idle timer.",
		"Expired sessions are removed when they are read.",
	} {
		if !strings.Contains(string(readme), sentence) {
			t.Fatalf("README missing sentence: %q", sentence)
		}
	}
	if !strings.Contains(string(readme), "## Expiry") {
		t.Fatal("README missing ## Expiry section")
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_expirydoc_test.go ; exit $rc

